import json,os,hashlib,stat,subprocess
from pathlib import Path
root=Path("/srv/projects")
targets={
 "iptvpn_old_multi_project_launcher":root/"iptvpn-bot/scripts/pm2-start-all.sh",
 "iptvpn_old_home_cleanup":root/"iptvpn-bot/scripts/home-cleanup.sh",
 "telegram_activate":root/"telegram-robot-leads/scripts/activate_project_only.py",
 "telegram_health":root/"telegram-robot-leads/scripts/lead_health.py",
}
out={"mode":"read_only","files":{},"references":{},"processes":[],"services":{},"scanned_files":0,"errors":[]}
for name,p in targets.items():
 r={"exists":p.exists(),"symlink":p.is_symlink()}
 if p.is_file() and not p.is_symlink():
  data=p.read_bytes()
  r.update(size=len(data),sha256=hashlib.sha256(data).hexdigest(),contains_global_pm2=b"/usr/bin/pm2" in data or b"/usr/lib/node_modules/pm2" in data or b"['pm2'" in data or b'["pm2"' in data or b"pm2 flush" in data,contains_old_root=b"/root/" in data,owner=p.stat().st_uid)
 out["files"][name]=r
bases=(Path("/etc/systemd/system"),Path("/etc/cron.d"),Path("/etc/cron.daily"),Path("/etc/cron.weekly"),Path("/usr/local/sbin"),Path("/usr/local/bin"),root/"iptvpn-bot/deploy",root/"iptvpn-bot/scripts",root/"iptvpn-bot/.github",root/"telegram-robot-leads/deploy",root/"telegram-robot-leads/scripts",root/"telegram-robot-leads/.github")
patterns=("home-cleanup.sh","pm2-start-all.sh","activate_project_only.py","lead_health.py")
for b in bases:
 if not b.is_dir():continue
 for current,dirs,files in os.walk(b,followlinks=False):
  if len(Path(current).relative_to(b).parts)>=5:dirs[:]=[]
  dirs[:]=[n for n in dirs if n not in ("node_modules",".git","archive","private","data","logs",".venv",".pm2","backups","tools")]
  for n in files:
   p=Path(current)/n
   try:
    if p.is_symlink() or not p.is_file() or p.stat().st_size>150000:continue
    if p.suffix not in ("",".sh",".py",".js",".service",".timer",".conf",".yaml",".yml",".json"):continue
    if p in targets.values():continue
    out["scanned_files"]+=1
    data=p.read_bytes()
    for t in patterns:
     if t.encode() in data:
      out["references"].setdefault(t,[]).append(str(p))
   except OSError as e:
    if len(out["errors"])<10:out["errors"].append(type(e).__name__)
for p in Path("/proc").iterdir():
 if not p.name.isdigit():continue
 try:
  cmd=(p/"cmdline").read_bytes()
  for t in patterns:
   if t.encode() in cmd:out["processes"].append({"pid":int(p.name),"target":t})
 except OSError:pass
for name in ("pm2-iptvpn-bot","pm2-telegram-robot-leads","pm2-root","lowcost-europa","pink-vpn"):
 q=subprocess.run(["systemctl","is-active",name],capture_output=True,text=True,timeout=5)
 out["services"][name]=q.stdout.strip()
print(json.dumps(out,sort_keys=True))
